sections.code:
// JavaScript is "call by sharing": every argument is passed BY VALUE,
// but for objects that value is a reference (a pointer to the heap object).

function reassign(obj) {
  obj = { name: 'replaced' }; // rebinds the LOCAL parameter only
}

function mutate(obj) {
  obj.name = 'mutated';       // follows the reference -> changes the shared object
}

function swap(a, b) {         // a classic C++ pass-by-reference exercise
  const tmp = a;
  a = b;
  b = tmp;                    // only the local copies are swapped
}

const user = { name: 'original' };
reassign(user);
console.log(user.name); // original

mutate(user);
console.log(user.name); // mutated

let x = 1, y = 2;
swap(x, y);
console.log(x, y);      // 1 2  (no change: JS has no pass-by-reference)

// Defensive copy when a function must not touch caller data:
function withBonus(player) {
  return { ...player, score: player.score + 50 }; // new object, caller untouched
}
const p = { name: 'Bob', score: 200 };
const q = withBonus(p);
console.log(p.score, q.score); // 200 250

// Parameters vs arguments: defaults, rest, and arity
function greet(greeting = 'Hello', ...names) {
  return `${greeting}, ${names.join(' & ') || 'stranger'}!`;
}
console.log(greet());                     // Hello, stranger!
console.log(greet(undefined, 'Ann'));     // Hello, Ann!  (undefined triggers the default)
console.log(greet(null, 'Ann'));          // null, Ann!   (null does NOT)
console.log(greet.length);                // 0  (params before the first default/rest)

sections.content:
**Scope** is the region of code in which a name refers to a particular variable. When code uses a name like `total`, the language must decide *which* `total` is meant. There are two strategies.

**Lexical (static) scope** — the binding is determined by the *textual structure* of the program. A function sees the variables of the blocks and functions it is *written inside*, regardless of who calls it. You can resolve every name by reading the source. JavaScript, Python, Java, C, Go, Rust, and nearly every modern language are lexically scoped.

**Dynamic scope** — the binding is determined by the *call stack at runtime*. A function sees the variables of whoever *called* it, then their caller, and so on. Early Lisps, Emacs Lisp (by default), and shell languages such as Bash (`local` variables are visible to called functions) are dynamically scoped. Perl offers both (`my` is lexical, `local` is dynamic).

```javascript
const level = 'global';
function show() { return level; }
function caller() {
  const level = 'caller';
  return show();
}
caller(); // 'global' — show() sees where it was written, not who called it
```

Under dynamic scope, `caller()` would return `'caller'`. Lexical scope wins in practice because it is **predictable** (you can reason about a function in isolation), **toolable** (editors and compilers resolve names statically, enabling fast variable lookup), and it is what makes **closures** meaningful.

JavaScript resolves a name by walking the **scope chain**: the current block, then each enclosing block and function, then the module scope, then the global scope. The first match wins (an inner declaration **shadows** an outer one of the same name). If nothing matches, reading throws a `ReferenceError`; in sloppy mode, *assigning* to an undeclared name silently creates a global — one reason strict mode and ES modules (strict by default) exist.

One part of JavaScript *feels* dynamic: `this`. Its value depends on *how* a function is called, not where it is written. We cover its rules later — and arrow functions exist largely to make `this` lexical too.

sections.code:
// ── Hoisting: declarations are registered before any code runs ──
console.log(typeof hoistedFn); // function  (whole function is hoisted)
console.log(v);                // undefined (var is hoisted AND initialised to undefined)
var v = 'var value';

function hoistedFn() { return 'ok'; }

// ── TDZ: let/const/class are hoisted but NOT initialised ──
try {
  console.log(l); // l exists in scope, but is in its Temporal Dead Zone
} catch (e) {
  console.log(e.constructor.name + ': ' + e.message);
  // ReferenceError: Cannot access 'l' before initialization
}
let l = 'let value';

// typeof is not a safe probe inside the TDZ either
try {
  typeof t;
} catch (e) {
  console.log('typeof in TDZ ->', e.constructor.name); // ReferenceError
}
const t = 1;

// ── Function expressions follow their variable's rules ──
try {
  arrow();
} catch (e) {
  console.log(e.constructor.name); // ReferenceError (const arrow is in TDZ)
}
const arrow = () => 'arrow';

// ── Block scope vs function scope ──
function scopes() {
  if (true) {
    var fnScoped = 'visible in whole function';
    let blockScoped = 'visible only in this block';
  }
  console.log(fnScoped);            // visible in whole function
  console.log(typeof blockScoped);  // undefined (not declared out here)
}
scopes();

// ── const freezes the BINDING, not the value ──
const cfg = { debug: false };
cfg.debug = true;       // fine: mutating the object
console.log(cfg.debug); // true
try {
  cfg = {};             // TypeError: Assignment to constant variable.
} catch (e) {
  console.log(e.constructor.name + ': ' + e.message);
}

sections.content:
The most famous closure bug looks like this:

```javascript
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}
// prints 3, 3, 3
```

Every callback closes over the **same** variable `i`, because `var` is function-scoped: there is only one `i` for the whole loop. The callbacks run after the loop has finished, when `i` is `3`. Nothing was "captured wrong" — closures capture variables, and there was only one variable.

**The fix is `let`.** The spec gives `for (let ...)` loops special behaviour: each iteration gets a **fresh binding** of `i`, initialised with the value from the end of the previous iteration. Each callback closes over its own `i`, so the output is `0, 1, 2`.

Before ES2015, the fix was an **IIFE** (Immediately Invoked Function Expression) that created a new function scope per iteration and passed the current value in as a parameter: `((n) => () => n)(i)`. You will still see this pattern in older codebases. Another pre-`let` fix was `arr.forEach((x, i) => ...)`, since each callback invocation has its own parameter `i`.

The same bug class shows up wherever a callback reads a variable that changes before the callback runs: event handlers registered in a loop, promises created in a loop, or React effects reading state that has since changed ("stale closures"). The diagnostic question is always the same: **how many bindings exist, and which one does this closure point to?**

sections.code:
// ── 1. Closures capture VARIABLES (bindings), not snapshots of values ──
function makeCounter() {
  let count = 0;                 // private: no outside code can reach it
  return {
    increment: () => ++count,
    get: () => count,
  };
}
const c1 = makeCounter();
const c2 = makeCounter();        // a fresh environment -> independent count
c1.increment(); c1.increment(); c2.increment();
console.log(c1.get(), c2.get()); // 2 1
console.log(c1.count);           // undefined (truly private)

// ── 2. The classic loop bug ──
const withVar = [];
for (var i = 0; i < 3; i++) withVar.push(() => i);   // ONE shared i
console.log(withVar.map((f) => f()));               // [ 3, 3, 3 ]

const withLet = [];
for (let j = 0; j < 3; j++) withLet.push(() => j);   // a NEW j per iteration
console.log(withLet.map((f) => f()));               // [ 0, 1, 2 ]

// Pre-ES2015 fix: an IIFE creates a new scope per iteration
const withIife = [];
for (var k = 0; k < 3; k++) withIife.push(((n) => () => n)(k));
console.log(withIife.map((f) => f()));              // [ 0, 1, 2 ]

// ── 3. Memoization: the cache lives in the closure ──
function memoize(fn) {
  const cache = new Map();
  return function (n) {
    if (cache.has(n)) return cache.get(n);
    const result = fn.call(this, n);
    cache.set(n, result);
    return result;
  };
}
let calls = 0;
const slowSquare = (n) => { calls++; return n * n; };
const fastSquare = memoize(slowSquare);
fastSquare(9); fastSquare(9); fastSquare(9);
console.log(fastSquare(9), 'computed', calls, 'time(s)'); // 81 computed 1 time(s)

// ── 4. Partial application and currying ──
const partial = (fn, ...preset) => (...rest) => fn(...preset, ...rest);
const log = (level, scope, msg) => `[${level}] ${scope}: ${msg}`;
const warnDb = partial(log, 'WARN', 'db');
console.log(warnDb('slow query'));        // [WARN] db: slow query

const curry = (fn) => function curried(...args) {
  return args.length >= fn.length
    ? fn(...args)
    : (...more) => curried(...args, ...more);
};
const add3 = curry((a, b, c) => a + b + c);
console.log(add3(1)(2)(3), add3(1, 2)(3), add3(1)(2, 3)); // 6 6 6

