sections.code:
'use strict'; // classes and ES modules are always strict

function whoAmI() { return this === undefined ? 'undefined' : this.name; }
const alice = { name: 'alice', whoAmI };
const bob = { name: 'bob' };

// Rule 4 — default binding: plain call -> undefined in strict mode
console.log(whoAmI());                   // undefined
// Rule 3 — implicit binding: obj.method() -> obj
console.log(alice.whoAmI());             // alice
// Losing the receiver: extracting the method drops the implicit binding
const detached = alice.whoAmI;
console.log(detached());                 // undefined
// Rule 2 — explicit binding: call / apply / bind
console.log(whoAmI.call(bob));           // bob
const bound = whoAmI.bind(bob);
console.log(bound.call(alice));          // bob  (bind wins over call)
// Rule 1 — new binding: this = the freshly created object
function Person(name) { this.name = name; }
console.log(new Person('carol').name);   // carol

// Arrow functions have no own `this`: they use the enclosing scope's this
class Timer {
  constructor() {
    this.ticks = 0;
  }
  startRegular() {
    return function () { return this; };  // gets its own this when called
  }
  startArrow() {
    return () => { this.ticks++; return this.ticks; }; // lexical this
  }
}
const timer = new Timer();
console.log(timer.startRegular()());     // undefined
const tick = timer.startArrow();
tick(); tick();
console.log(tick());                     // 3

// Higher-order functions: callbacks that receive/return functions
const orders = [
  { id: 1, total: 40, paid: true },
  { id: 2, total: 15, paid: false },
  { id: 3, total: 90, paid: true },
];
const revenue = orders
  .filter((o) => o.paid)            // keep paid orders
  .map((o) => o.total)              // project to totals
  .reduce((sum, t) => sum + t, 0);  // fold into one number
console.log(revenue);                    // 130
